import fs from "node:fs";
import path from "node:path";
import type { ServiceSlug } from "./site";

export type Tone = "oak" | "tile" | "paint" | "dry" | "linen";

export type Img = {
  src: string;
  width: number;
  height: number;
  /** true once the real photo exists in /public – otherwise a styled placeholder is rendered */
  exists: boolean;
  tone: Tone;
  /** WebP variants generated by scripts/optimize-images.py (smallest first) */
  webp: { src: string; w: number }[];
};

/** Reads the pixel width from a JPEG header (SOF marker) – no extra dependency. */
function actualWidth(src: string): number | null {
  try {
    const buf = fs.readFileSync(path.join(process.cwd(), "public", src));
    let i = 2;
    while (i < buf.length) {
      if (buf[i] !== 0xff) return null;
      const marker = buf[i + 1];
      const len = buf.readUInt16BE(i + 2);
      if (marker >= 0xc0 && marker <= 0xc3) return buf.readUInt16BE(i + 7);
      i += 2 + len;
    }
  } catch {
    /* ignore */
  }
  return null;
}

/** Build-time check (static export) whether a photo was added to /public. */
function img(src: string, width: number, height: number, tone: Tone): Img {
  const pub = (p: string) => fs.existsSync(path.join(process.cwd(), "public", p));
  const exists = pub(src);
  const base = src.replace(/\.jpe?g$/i, "");
  const webp: Img["webp"] = [];
  if (exists) {
    for (const w of [480, 800]) if (pub(`${base}-${w}.webp`)) webp.push({ src: `${base}-${w}.webp`, w });
    if (pub(`${base}.webp`)) webp.push({ src: `${base}.webp`, w: actualWidth(src) ?? width });
  }
  return { src, width, height, exists, tone, webp };
}

const SERVICE_TONE: Record<ServiceSlug, Tone> = {
  bodenbelaege: "oak",
  fliesen: "tile",
  malerarbeiten: "paint",
  trockenbau: "dry",
  renovierung: "linen",
};

export const images = {
  hero: () => img("/images/hero.jpg", 1200, 1500, "oak"),
  team: () => img("/images/team.jpg", 1125, 1406, "linen"),
  service: (slug: ServiceSlug) => img(`/images/leistungen/${slug}.jpg`, 1200, 1500, SERVICE_TONE[slug]),
  project: (n: number, tone: Tone) => img(`/images/projekte/projekt-${n}.jpg`, 900, 1200, tone),
  before: () => img("/images/vorher-nachher/vorher.jpg", 1800, 1200, "dry"),
  after: () => img("/images/vorher-nachher/nachher.jpg", 1800, 1200, "oak"),
};
